import{_ as a,o as i,c as o,a6 as r}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Organizar automatizaciones","description":"","frontmatter":{"title":"Organizar automatizaciones","docId":"user.automations.index","translationKey":"user.automations.index","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"33d5d9aa4db49a70a3b416ea817479822f06d7cb028699ab9bd344c14cd79892","translationRevision":"263525674f1738f21116ff09917f6a646ec829b8ded3e6e9187b56b03225b923","order":10},"headers":[],"relativePath":"es/user/automations/index.md","filePath":"es/user/automations/index.md","lastUpdated":1794611623000}'),s={name:"es/user/automations/index.md"};function n(t,e,l,c,d,u){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="organize-automations" tabindex="-1">Organizar automatizaciones <a class="header-anchor" href="#organize-automations" aria-label="Permalink to &quot;Organizar automatizaciones {#organize-automations}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Construye una biblioteca pequeña y comprensible que responda a eventos LIVE. Necesitas el host de escritorio funcionando. Una <a href="./../live/connections.html">conexión LIVE</a> real permite validar eventos externos; las acciones de plugins también requieren su plugin y servicio preparados.</p><h2 id="understand-the-library" tabindex="-1">Comprender la biblioteca <a class="header-anchor" href="#understand-the-library" aria-label="Permalink to &quot;Comprender la biblioteca {#understand-the-library}&quot;">​</a></h2><p>Una <strong>Action</strong> es una operación reutilizable configurada, como escribir una línea o reproducir sonido. Un <strong>Event</strong> elige disparador, filtros, espera y acciones vinculadas. Un perfil agrupa definiciones para un flujo de trabajo; solo hay un paquete de perfil activo a la vez. Las <a href="./variables.html">Variables</a> proporcionan valores reutilizables por varias acciones.</p><ol><li>Abre <strong>Automations</strong> y confirma el perfil activo antes de editar. Busca Eventos y Acciones por separado para saber qué tipo de registro seleccionas.</li><li>Comienza con la <a href="./first-rule.html">primera regla de registro</a>. Crea la acción y después el evento que la referencia.</li><li>Elige un disparador admitido por el host. Añade filtros mediante el selector de campos correspondiente. Varias condiciones restringen la coincidencia; no modifican el contenido entrante.</li><li>Define el tiempo de espera y su ámbito. Una espera global limita la regla entre todos los espectadores; una espera por usuario los controla por separado.</li><li>Vincula las acciones deseadas en orden. El modo normal ejecuta la lista elegida; el aleatorio selecciona una acción. Una acción de demora pospone las posteriores sin frenar la recepción LIVE.</li><li>Guarda, revisa los cambios de definición que se muestren y activa explícitamente los registros deseados. Consulta el historial para comprobar nombre, resultado y error.</li></ol><p>Las pruebas pueden ejecutar los efectos configurados. Lee la lista seleccionada antes de pulsar <strong>Test</strong> o disparar un evento, especialmente si incluye audio, HTTP, puntos o plugins. Aprende primero con registros.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>Están disponibles la edición local, la ejecución, las plantillas, los perfiles y el historial. Los disparadores de plugins aparecen mientras su plugin está instalado y activo. La activación depende de la superficie y de los valores enabled revisados; comprueba eventos y acciones antes de confirmar. <strong>Changes</strong> en Eventos/Acciones es una <a href="./../cloud/changes.html">comparación local</a>, sin subida automática a Cloud.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Si no se ejecuta, comprueba perfil activo, interruptores, disparador, filtros, espera y acciones ausentes, en ese orden. Ante un conflicto de revisión, vuelve a leer la definición guardada y revísala. Evita sobrescribir a ciegas cambios ajenos. Exporta un <a href="./templates.html">perfil</a> conocido antes de modificaciones amplias.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>Antes de cambiar perfil/importar, lee <a href="./templates.html#operational-details">activación por superficie</a>. El cambio puede activar miembros deshabilitados individualmente. El cooldown vive en memoria, con máximo 24 horas; sin uniqueId los espectadores comparten ámbito anónimo. La tabla se vacía al alcanzar 8.192 claves: sobrecarga o reinicio pueden permitir ejecuciones adicionales. No es cuota durable ni garantía de replay.</p>',13)])])}const b=a(s,[["render",n]]);export{m as __pageData,b as default};
